// Get site-cookie mapping list from referenced node
const siteCookieMap = $("domain_cookie_mapping").all().map(item => item.json);

// Helper: Get cookie by matching link with site
function get_cookie_from_link(link) {
  if (!link) return null;

  for (const mapping of siteCookieMap) {
    const { site, cookie } = mapping;
    if (site && link.toLowerCase().includes(site.toLowerCase())) {
      return cookie;
    }
  }
  return null;
}

// Process each input item
const output = $input.all().map(item => {
  const url = item.json.url;
  item.json.cookie = get_cookie_from_link(url);
  return item;
});

return output;

