// --- configuration ---
const MAX_WORDS = 57;
const MIN_ASCII_RATIO = 0.75;
const MIN_ENGLISH_WORD_RATIO = 0.25;
const SHORT_TEXT_WORDS = 12;

// --- English connectors ---
const englishCore = new Set([
  "the","of","and","to","in","a","for","is","on","with","at","by","from",
  "that","this","an","be","it","as","was","are","have","has","will","not",
  "new","after","over","under","against","president","minister","meeting",
  "war","election","russia","china","ukraine","nato","united","states",
  "europe","military","government","prime","official","reports","world",
  "foreign","security","conflict","summit","statement","plan"
]);

function isMostlyAscii(text) {
  const asciiChars = (text.match(/[a-zA-Z0-9\s.,'";:!?()\-]/g) || []).length;
  return asciiChars / (text.length || 1) >= MIN_ASCII_RATIO;
}

function englishWordRatio(text) {
  const words = text.toLowerCase().split(/\W+/);
  let count = 0;
  for (const w of words) if (englishCore.has(w)) count++;
  return count / (words.length || 1);
}

// detect heavy foreign patterns like accented letters or double consonants
function looksForeign(text) {
  return /[àáâãäåæçèéêëìíîïñòóôõöøùúûüýÿßœčšž]/i.test(text);
}

function isEnglish(text) {
  if (!isMostlyAscii(text)) return false;

  const ratio = englishWordRatio(text);
  const wordCount = text.split(/\s+/).length;

  // 1️⃣ automatic pass for very short clean ASCII headlines
  if (wordCount <= SHORT_TEXT_WORDS && !looksForeign(text)) return true;

  // 2️⃣ normal case
  if (ratio >= MIN_ENGLISH_WORD_RATIO) return true;

  // 3️⃣ fallback: low ratio but no foreign patterns → still English
  if (!looksForeign(text)) return true;

  // otherwise clearly foreign
  return false;
}

function cleanFormerPresident(text) {
  return text.replace(/\bformer president\s+(donald\s+trump( jr)?|eric\s+trump)\b/gi, "$1");
}

// --- main ---
const output = [];
const rejected = [];

for (const item of $input.all()) {
  let content = (item.json.post_content || item.json.text || "").trim();
  content = cleanFormerPresident(content);

  const wordCount = content.split(/\s+/).length;
  const english = isEnglish(content);
  const passes = english && wordCount <= MAX_WORDS;

  if (passes) {
    item.json.post_content = content;
    output.push(item);
  } else {
    item.json.filter_reason = !english
      ? "Non-English"
      : wordCount > MAX_WORDS
      ? `Too long (${wordCount} words)`
      : "Other filter trigger";
    rejected.push(item);
  }
}

console.log(`✅ English passed: ${output.length}, ❌ Rejected: ${rejected.length}`);
return output;

const title = ($json.title || '').replace(/\s+/g, ' ').trim();
const desc  = ($json.description || '').replace(/\s+/g, ' ').trim();

// build text for embedding
let textForEmbedding;
if (title && desc) {
  textForEmbedding = `${title} - ${desc}`;
} else {
  textForEmbedding = title || desc;
}

return {
  ...$json, // keep url, url_hash, etc.
  textForEmbedding
};

function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const points = items.map(item => ({
  id: uuid(),
  vector: item.json.data[0].embedding,
  payload: {
    content: item.json.textForEmbedding || "",
    url: item.json.url || "",
    urlHash: item.json.url_hash || "",
    publishedAt: item.json.publishedAt
      ? Math.floor(new Date(item.json.publishedAt).getTime() / 1000)
      : Math.floor(Date.now() / 1000)
  }
}));

return [{ json: { points } }];

function sanitizeValue(value) {
  if (typeof value === "string") {
    return value
      // remove smart quotes & odd unicode quotes
      .replace(/[\u201C\u201D\u201E\u201F\u2033\u2036]/g, "")
      // remove standard double quotes
      .replace(/"/g, "")
      // normalize line breaks
      .replace(/\r?\n|\r/g, " ")
      // normalize whitespace
      .replace(/\s+/g, " ")
      .trim();
  }

  if (Array.isArray(value)) {
    return value.map(sanitizeValue);
  }

  if (value !== null && typeof value === "object") {
    const cleaned = {};
    for (const key in value) {
      cleaned[key] = sanitizeValue(value[key]);
    }
    return cleaned;
  }

  // numbers, booleans, null remain untouched
  return value;
}

// n8n input may be an array of items
return items.map(item => ({
  json: sanitizeValue(item.json)
}));
